<input type="hidden" name="commerce_settings_present" value="1"><h2><?=e(t('เก็บเงินปลายทาง (COD)'))?></h2><label class="checkbox"><input type="checkbox" name="cod_enabled" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['cod_enabled']):!empty($bank['cod_enabled']))?'checked':''?>> เปิดบริการ COD</label><?php field('cod_min','ยอดสุทธิขั้นต่ำ COD (บาท)','text',$_SERVER['REQUEST_METHOD']==='POST'?post('cod_min'):($bank['cod_min']??'0.00'));field('cod_max','ยอดสุทธิสูงสุด COD (บาท)','text',$_SERVER['REQUEST_METHOD']==='POST'?post('cod_max'):($bank['cod_max']??'1000000.00')); ?><label>จังหวัดที่รองรับ COD (จังหวัดละบรรทัด เว้นว่าง = ทุกจังหวัด)<textarea name="cod_provinces" maxlength="10000"><?=e($_SERVER['REQUEST_METHOD']==='POST'?post('cod_provinces'):($bank['cod_provinces']??''))?></textarea></label>
<hr><h2>QR PromptPay</h2><p>ใช้ผู้รับเงินจริงของร้านเท่านั้น QR ระบุยอดถูกสร้างภายในเว็บไซต์ ไม่ส่งข้อมูลไปบริการ QR ภายนอก และยังต้องตรวจยอดเข้าจริงก่อนอนุมัติ</p><label class="checkbox"><input type="checkbox" name="promptpay_enabled" <?=($_SERVER['REQUEST_METHOD']==='POST'?isset($_POST['promptpay_enabled']):!empty($bank['promptpay_enabled']))?'checked':''?>> เปิด QR PromptPay</label><label>ประเภทผู้รับ<select name="promptpay_type"><option value="phone" <?=(($_SERVER['REQUEST_METHOD']==='POST'?post('promptpay_type'):($bank['promptpay_type']??'phone'))==='phone')?'selected':''?>>เบอร์โทรศัพท์มือถือ</option><option value="national_id" <?=(($_SERVER['REQUEST_METHOD']==='POST'?post('promptpay_type'):($bank['promptpay_type']??''))==='national_id')?'selected':''?>>เลขประจำตัวประชาชน 13 หลัก</option></select></label><?php field('promptpay_recipient','หมายเลขพร้อมเพย์จริง','text',$_SERVER['REQUEST_METHOD']==='POST'?post('promptpay_recipient'):($bank['promptpay_recipient']??''),false);field('promptpay_name','ชื่อผู้รับเงินจริง','text',$_SERVER['REQUEST_METHOD']==='POST'?post('promptpay_name'):($bank['promptpay_name']??''),false); ?><label class="checkbox"><input type="checkbox" name="promptpay_confirm" value="1"> ยืนยันว่าพร้อมเพย์นี้ผูกกับบัญชีจริงของร้านและทดสอบรับเงินได้แล้ว</label><hr><h2><?=e(t('โอนเงินผ่านธนาคาร'))?></h2>
